mapper.sql:
select pt.id, pt.code, pt.source_id as sourceId, pt.source_code as sourceCode, pt.source_type as sourceType, pt.delivery_qty as deliveryQty, pt.warehouse_id as warehouseId, pt.warehouse_name as warehouseName, pt.create_user_name as createUserName, pt.create_time as createTime, pt.packing_status as packingStatus, pt.weighting_status as weightingStatus from packing_task pt where pt.is_deleted = FALSE
and pt.source_code ILIKE concat('%',#{params.sourceCode}::text,'%')
and ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pt.create_time DESC

mapper.select:
SELECT packing_status as type, COUNT(*) AS count FROM ( SELECT pt.id, pt.packing_status FROM packing_task pt where pt.is_deleted = FALSE
${permissionSql}
) AS subquery GROUP BY packing_status

SELECT pt.id, pt.source_code as sourceCode, pt.packing_status as packingStatus, pt.weighting_status as weightingStatus, (SELECT CASE WHEN error_msg is null or error_msg = '' THEN '' ELSE concat('第',wc.box_no,'箱:',wc.error_msg) END AS errorMsg FROM wms_carton wc WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE order by wc.create_time DESC limit 1) as errorMsg, (SELECT COALESCE(SUM(wcd.pack_qty), 0) FROM wms_carton wc LEFT JOIN wms_carton_detail wcd ON wcd.main_id = wc.id and wcd.is_deleted = false WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE) as packedQty, (SELECT COALESCE(SUM(wcs.package_weight), 0) FROM wms_carton_spec wcs WHERE wcs.main_id = pt.ID AND wcs.is_deleted = FALSE) as packingWeight, (SELECT COALESCE(SUM(pd.qty), 0) FROM picking_lists pl LEFT JOIN picking_detail pd on pd.main_id = pl.id and pd.is_deleted = FALSE WHERE pl.source_id = pt.source_id AND pl.is_deleted = FALSE) as pickQty FROM packing_task pt where pt.is_deleted = FALSE and pt.source_type in ('B2B')
AND pt.id IN
#{item}
AND pt.source_code IN
#{item}
group by pt.id,pt.source_code,pt.packing_status,pt.weighting_status

SELECT DISTINCT wc.id, wc.packing_task_id as taskId, wc.box_no, concat(wcs.box_length, wcs.size_unit,'*', wcs.box_width, wcs.size_unit,'*', wcs.box_height,wcs.size_unit) AS boxSize, wcs.package_weight, wcs.weight_unit, wc.weighting_status, wc.packing_status, wc.packing_user_name, wcs.measure_source, wc.error_msg, wcs.box_length as length, wcs.box_width as width, wcs.box_height as height, (select string_agg(wcd.sku_no|| '*' || wcd.pack_qty, ';') from wms_carton_detail wcd where wcd.is_deleted = false and wcd.main_id = wc.id) as sku FROM wms_carton wc INNER JOIN wms_carton_spec wcs ON wcs.id = wc.spec_id AND wcs.is_deleted = FALSE JOIN wms_carton_detail wcd ON wcd.main_id = wc.id and wcd.is_deleted = FALSE WHERE wc.is_deleted = FALSE AND wcd.pack_qty > 0
AND wc.packing_task_id = #{params.taskId}
AND wc.id IN
#{id}
${params.permissionSql}
ORDER BY wc.box_no

SELECT
wc.id, wc.packing_task_id as taskId, wc.box_no, concat(wcs.box_length, wcs.size_unit,'*', wcs.box_width, wcs.size_unit,'*', wcs.box_height,wcs.size_unit) AS boxSize, wcs.package_weight, wcs.weight_unit, wc.weighting_status, wc.packing_status, wc.packing_user_name, wcs.measure_source, wc.error_msg, pt.source_id , wcs.box_length as length, wcs.box_width as width, wcs.box_height as height, wcd.sku_id, wcd.sku_no, wcd.pack_qty, wcd.fn_sku, wcd.sku_no AS sku, fsp.box_no as outCode FROM wms_carton_detail wcd INNER JOIN wms_carton wc ON wc.id = wcd.main_id AND wc.is_deleted = FALSE JOIN wms_carton_spec wcs ON wc.spec_id = wcs.id and wcs.is_deleted = FALSE JOIN packing_task pt ON wc.packing_task_id = pt.id and pt.is_deleted = FALSE LEFT JOIN fba_shipment_packing fsp on fsp.carton_id = wc.id and fsp.is_deleted =false WHERE ${params.sqlMap.default} and wcd.is_deleted = FALSE AND wcd.pack_qty > 0
AND wc.packing_task_id IN
#{id}
${permissionSql}
ORDER BY pt.source_code,wc.box_no

SELECT pt.id, pt.source_code as sourceCode, pt.packing_status as packingStatus, pt.weighting_status as weightingStatus, (SELECT CASE WHEN error_msg is null or error_msg = '' THEN '' ELSE concat('第',wc.box_no,'箱:',wc.error_msg) END AS errorMsg FROM wms_carton wc WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE order by wc.create_time DESC limit 1) as errorMsg, (SELECT COALESCE(SUM(wcd.pack_qty), 0) FROM wms_carton wc LEFT JOIN wms_carton_detail wcd ON wcd.main_id = wc.id and wcd.is_deleted = false WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE) as packedQty, (SELECT COALESCE(SUM(wcs.package_weight), 0) FROM wms_carton_spec wcs WHERE wcs.main_id = pt.ID AND wcs.is_deleted = FALSE) as packingWeight, COALESCE ( (SELECT SUM(rad.picking_qty) FROM requisition_application ra LEFT JOIN requisition_application_detail rad on ra.id = rad.main_id and rad.is_deleted = FALSE WHERE ra.id = pt.source_id AND ra.is_deleted = FALSE),(SELECT SUM(rad.picking_qty) FROM first_mile_delivery fmd LEFT JOIN requisition_application_detail rad on fmd.source_id = rad.main_id and rad.is_deleted = FALSE WHERE fmd.id = pt.source_id AND fmd.is_deleted = FALSE),0) as pickQty FROM packing_task pt where pt.is_deleted = FALSE and pt.source_type in ('FBA','thirdWarehouse')
AND pt.id IN
#{item}
AND pt.source_code IN
#{item}
group by pt.id,pt.source_code,pt.packing_status,pt.weighting_status
